-- Skrypt bazy klubu sportowego, który NIE chce się wykonać.
-- Są w nim trzy błędy. Uruchamiaj, czytaj komunikat, poprawiaj — aż przejdzie cały.
CREATE TABLE zawodnik (
  id_zawodnika INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  imie VARCHAR(30) NOT NULL,
  nazwisko VARCHAR(40) NOT NULL,
  id_druzyny INT NOT NULL,
  FOREIGN KEY (id_druzyny) REFERENCES druzyna(id_druzyny)
);

CREATE TABLE druzyna (
  id_druzyny INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  nazwa VARCHAR(50) NOT NULL,
  miasto VARCHAR(40) NOT NULL
);

CREATE TABLE mecz (
  id_meczu INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  data_meczu DATE NOT NULL,
  gospodarz VARCHAR(50) NOT NULL,
  FOREIGN KEY (gospodarz) REFERENCES druzyna(nazwa)
);
